<?php
require_once __DIR__.'/../includes/bootstrap.php';
$user=lh_user();if(!$user){header('Location:/creator-ai/auth/google-login.php');exit;}
$rows=[];try{$q=$db->prepare("SELECT p.*,l.title lesson_title,c.title course_title FROM learning_progress p JOIN learning_lessons l ON l.id=p.lesson_id JOIN learning_courses c ON c.id=l.course_id WHERE p.user_id=? ORDER BY p.updated_at DESC");$q->execute([(int)$user['id']]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Learning</title><style>body{margin:0;font-family:Inter,Arial;background:#f7f9fd;color:#172033}.wrap{width:min(900px,calc(100% - 28px));margin:auto;padding:40px 0}.card{background:#fff;border:1px solid #e5e8ef;border-radius:16px;padding:18px;margin:10px 0}.bar{height:8px;background:#eceef4;border-radius:10px;overflow:hidden;margin-top:10px}.bar i{display:block;height:100%;background:#635bff}.back{color:#635bff;font-weight:800;font-size:13px}</style></head><body><main class="wrap"><a class="back" href="/learning-hub/">← Learning Hub</a><h1>My Learning</h1><p>Welcome, <?=lh_h($user['name']??'Learner')?>.</p><?php foreach($rows as $r):?><div class="card"><b><?=lh_h($r['lesson_title'])?></b><div><?=lh_h($r['course_title'])?></div><div class="bar"><i style="width:<?=min(100,(int)$r['progress_percent'])?>%"></i></div><small><?=number_format((int)$r['progress_percent'])?>% complete</small></div><?php endforeach;if(!$rows):?><div class="card">No progress yet. <a href="/learning-hub/courses.php">Start a course →</a></div><?php endif;?></main></body></html>
